---- MONITORS ----
------------------

-- See https://wiki.hypr.land/configuring/core/monitors/
-- Any display not listed below (a projector, a conference-room screen) goes
-- directly right of the laptop panel with the top edges level, so the pointer
-- crosses anywhere along the shared edge. "auto" would put it at y=0, which
-- only touches the laptop (at y=840) by a sliver or a corner.
hl.monitor({
    output   = "",
    mode     = "preferred",
    position = "8360x840",
    scale    = 1,
})

-- Desk layout, same as COSMIC (outputs.ron / dock-monitor-layout), left to right.
-- Matched by description because the dock's DP-N numbers change on every attach.
hl.monitor({ output = "desc:Dell Inc. DELL P2425HE 8BY1H14",                 mode = "1920x1080@60",     position = "0x840",    scale = 1 })
hl.monitor({ output = "desc:Dell Inc. DELL P2214H KW14V59N39RB",             mode = "1920x1080@60",     position = "1920x0",   scale = 1, transform = 1 })  -- portrait
hl.monitor({ output = "desc:Samsung Electric Company S34J55x H4LR305255",    mode = "3440x1440@59.973", position = "3000x480", scale = 1 })
hl.monitor({ output = "eDP-1",                                               mode = "1920x1080@60.049", position = "6440x840", scale = 1 })

-- The layout saved from Settings > Displays (display-layout save) replaces the rules above,
-- monitor by monitor (same output keys, and hl.monitor merges); delete the file to go back to
-- them. Loaded guardedly, like layouts.lua: a mistake there must not take this config down.
do
    local path = os.getenv("HOME") .. "/.config/hypr/monitors.lua"
    local f = io.open(path, "r")
    if f then
        f:close()
        local ok, err = pcall(dofile, path)
        if not ok then hl.notification.create({ text = "monitors.lua: " .. tostring(err), duration = 10000 }) end
    end
end


