-- Set programs that you use
local terminal    = "uwsm app -- ghostty"
-- Starts emacs.service first if the daemon isn't up (it only autostarts with
-- graphical-session.target, i.e. the uwsm-managed session).
local editor      = "uwsm app -- sh -c 'emacsclient -c || { systemctl --user start emacs.service && emacsclient -c; }'"
local browser     = "uwsm app -- firefox"
local fileManager = "uwsm app -- nautilus"
local menu        = 'fuzzel --launch-prefix="uwsm app -- "'

-- Hyprland throws away the output of everything it starts. run-logged runs the command and,
-- only when it fails, writes its exit status and last stderr lines to the user journal
-- (journalctl --user -t run-logged). Every exec_cmd below, autostart and bindings, goes through it.
do
    local function logged(cmd)
        if type(cmd) ~= "string" then return cmd end
        local quoted = cmd:gsub("'", "'\\''")
        return "$HOME/.local/bin/run-logged '" .. quoted .. "'"
    end
    local raw_exec, raw_bind = hl.exec_cmd, hl.dsp.exec_cmd
    pcall(function() hl.exec_cmd = function(cmd, ...) return raw_exec(logged(cmd), ...) end end)
    pcall(function() hl.dsp.exec_cmd = function(cmd, ...) return raw_bind(logged(cmd), ...) end end)
end


