-- See https://wiki.hypr.land/configuring/core/autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
hl.on("hyprland.start", function ()
    -- Quickshell is the whole shell: bar, control panel (Super+C), launcher (Super+D),
    -- overview (Super+Tab), notifications and level popups. Config in ~/.config/quickshell.
    -- It also draws the wallpaper. hyprpaper (the plain image) is not started here: Quickshell
    -- runs it only while its own wallpaper is hidden, and quickshell-start falls back to it
    -- if Quickshell does not come up.
    hl.exec_cmd("$HOME/.local/bin/quickshell-start")
    -- hypridle (idle lock and screen blanking) is started by its systemd user service,
    -- hypridle.service; starting it here too gave two copies (2026-11-11).
    -- clipboard history for Super+V (text and images)
    hl.exec_cmd("uwsm app -- wl-paste --type text --watch cliphist store")
    hl.exec_cmd("uwsm app -- wl-paste --type image --watch cliphist store")
    -- mount USB drives / SD cards with a notification (the drives pill on the bar ejects them)
    hl.exec_cmd("uwsm app -- udiskie --automount --notify --no-tray")
    -- night light: hyprsunset.service (Hyprland-only drop-in), schedule in hyprsunset.conf
    -- dark/light follows the same schedule: theme-by-time.timer (Hyprland-only); run once now
    hl.exec_cmd("systemctl --user start theme-by-time.service")
    hl.exec_cmd("$HOME/.local/bin/input-settings apply")      -- input overrides saved from Settings > Input (~/.config/shell/input.json)
    -- low-battery warnings (15% and 5%) come from Quickshell: BatteryWarn.qml
    hl.exec_cmd("systemctl --user start hyprpolkitagent")
end)


