-- Curves and animations, see https://wiki.hypr.land/configuring/core/animations/
-- Changed from the stock set (kept in hyprland.lua.default): desktops slide a short
-- way while fading instead of cross-fading; launcher/panel/popups pop in; windows
-- close quicker. Opening and moving windows keep the stock spring.
hl.curve("easeOutQuint",   { type = "bezier", points = { {0.23, 1},    {0.32, 1}    } })
hl.curve("easeInOutCubic", { type = "bezier", points = { {0.65, 0.05}, {0.36, 1}    } })
hl.curve("linear",         { type = "bezier", points = { {0, 0},       {1, 1}       } })
hl.curve("almostLinear",   { type = "bezier", points = { {0.5, 0.5},   {0.75, 1}    } })
hl.curve("quick",          { type = "bezier", points = { {0.15, 0},    {0.1, 1}     } })
-- Fast start, long soft landing: used for desktop switches, popups and closing windows.
hl.curve("snap",           { type = "bezier", points = { {0.16, 1},    {0.3, 1}     } })

-- Default springs
hl.curve("easy",           { type = "spring", mass = 1, stiffness = 238.1191, damping = 24.21279333 })

-- Three feels to choose from; `anim-preset NAME` switches live and remembers it
-- (~/.local/state/anim-preset). Each row: leaf, speed, curve (spring if it names
-- one), style. "dim" is how much unfocused windows darken (0 = not at all).
Anim = { current = "snappy", springs = { easy = true } }
Anim.presets = {
    -- quick and a little lively: desktops slide a short way while fading
    snappy = { dim = 0.10, rows = {
        { "global", 10, "default" }, { "border", 5.39, "easeOutQuint" },
        { "windows", 4.79, "easy" }, { "windowsIn", 4.1, "easy", "popin 87%" }, { "windowsOut", 2.2, "snap", "popin 92%" },
        { "fadeIn", 1.73, "almostLinear" }, { "fadeOut", 2, "snap" }, { "fade", 3.03, "quick" },
        { "layers", 3.81, "easeOutQuint" }, { "layersIn", 3.2, "snap", "popin 94%" }, { "layersOut", 2, "snap", "popin 96%" },
        { "fadeLayersIn", 1.79, "almostLinear" }, { "fadeLayersOut", 1.39, "almostLinear" },
        { "workspaces", 3.6, "snap", "slidefade 18%" }, { "workspacesIn", 3.6, "snap", "slidefade 18%" }, { "workspacesOut", 3.6, "snap", "slidefade 18%" },
        { "zoomFactor", 7, "quick" } } },
    -- slower and softer: everything fades, nothing slides, no dimming
    calm = { dim = 0, rows = {
        { "global", 10, "default" }, { "border", 6, "easeOutQuint" },
        { "windows", 6, "easeOutQuint" }, { "windowsIn", 6, "easeOutQuint", "popin 95%" }, { "windowsOut", 4, "easeOutQuint", "popin 97%" },
        { "fadeIn", 3, "easeOutQuint" }, { "fadeOut", 3, "easeOutQuint" }, { "fade", 4, "easeOutQuint" },
        { "layers", 5, "easeOutQuint" }, { "layersIn", 5, "easeOutQuint", "fade" }, { "layersOut", 3.5, "easeOutQuint", "fade" },
        { "fadeLayersIn", 3, "easeOutQuint" }, { "fadeLayersOut", 2.5, "easeOutQuint" },
        { "workspaces", 4, "easeOutQuint", "fade" }, { "workspacesIn", 4, "easeOutQuint", "fade" }, { "workspacesOut", 4, "easeOutQuint", "fade" },
        { "zoomFactor", 7, "quick" } } },
    -- what Hyprland ships (and what this config had before 2026-11-10)
    stock = { dim = 0, rows = {
        { "global", 10, "default" }, { "border", 5.39, "easeOutQuint" },
        { "windows", 4.79, "easy" }, { "windowsIn", 4.1, "easy", "popin 87%" }, { "windowsOut", 1.49, "linear", "popin 87%" },
        { "fadeIn", 1.73, "almostLinear" }, { "fadeOut", 1.46, "almostLinear" }, { "fade", 3.03, "quick" },
        { "layers", 3.81, "easeOutQuint" }, { "layersIn", 4, "easeOutQuint", "fade" }, { "layersOut", 1.5, "linear", "fade" },
        { "fadeLayersIn", 1.79, "almostLinear" }, { "fadeLayersOut", 1.39, "almostLinear" },
        { "workspaces", 1.94, "almostLinear", "fade" }, { "workspacesIn", 1.21, "almostLinear", "fade" }, { "workspacesOut", 1.94, "almostLinear", "fade" },
        { "zoomFactor", 7, "quick" } } },
}
Anim.file = (os.getenv("XDG_STATE_HOME") or (os.getenv("HOME") .. "/.local/state")) .. "/anim-preset"

function Anim.use(name, remember)
    local p = Anim.presets[name]
    if not p then return false end
    for _, r in ipairs(p.rows) do
        local a = { leaf = r[1], enabled = true, speed = r[2], style = r[4] }
        if Anim.springs[r[3]] then a.spring = r[3] else a.bezier = r[3] end
        hl.animation(a)
    end
    hl.config({ decoration = { dim_inactive = p.dim > 0, dim_strength = p.dim } })
    Anim.current = name
    if remember then
        local f = io.open(Anim.file, "w")
        if f then f:write(name, "\n"); f:close() end
    end
    return true
end

do
    local f = io.open(Anim.file, "r")
    local saved = f and f:read("l")
    if f then f:close() end
    if not Anim.use(saved or "snappy") then Anim.use("snappy") end
end

