local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- How the modifiers read (2026-11-16):
--   Super            open or go to something
--   Super+Shift      the same key, the other way round: send there, the reverse, the variant
--                    (S scratchpad, R record, digits, arrows, `, Print, Y, I/U, Return main window),
--                    plus the window modes Shift+V float and Shift+P own size, and Shift+E log out
--   Super+Ctrl       adjust: window sizes (arrows, \ reset), theme T, mic M, webcam W, colour C,
--                    recording options R, push to talk Space
--   Super+Alt        tab groups
--   Super+Z, then    lecture tools (D draw, L spotlight, K keys, Z the menu)
-- Keys that moved that day still work until MOVED_UNTIL, and say where they went.
local MOVED_UNTIL = os.time({ year = 2026, month = 11, day = 30, hour = 23 })
local function moved(old, new, run, opts)
    if os.time() > MOVED_UNTIL then return end
    opts = opts or {}
    hl.bind(mainMod .. " + " .. old, function()
        hl.notification.create({ text = "That key moved: it is now " .. new, duration = 3500 })
        hl.dispatch(run)
    end, { locked = opts.locked })
end

-- Example binds, see https://wiki.hypr.land/configuring/core/binds/ for more
hl.bind(mainMod .. " + Return",    hl.dsp.exec_cmd(editor), { description = "Emacs" })  -- same as COSMIC
hl.bind(mainMod .. " + T",         hl.dsp.exec_cmd(terminal), { description = "Terminal" })
hl.bind(mainMod .. " + B",         hl.dsp.exec_cmd(browser), { description = "Firefox" })
hl.bind(mainMod .. " + E",         hl.dsp.exec_cmd(fileManager), { description = "Files" })
-- Quickshell's launcher; fuzzel only as the emergency launcher if Quickshell is down
hl.bind(mainMod .. " + D",         hl.dsp.exec_cmd("$HOME/.nix-profile/bin/qs ipc call launcher toggle || " .. menu), { description = "App launcher" })
-- Tapping Super alone also opens it, as in COSMIC.  A release bind fires only if
-- nothing else was pressed while Super was held, so Super+key combos skip it.
hl.bind("SUPER + Super_L",     hl.dsp.exec_cmd("$HOME/.nix-profile/bin/qs ipc call launcher toggle || " .. menu), { release = true, description = "App launcher (tap Super)" })
hl.bind(mainMod .. " + Space",     hl.dsp.exec_cmd("hyprctl switchxkblayout all next"), { description = "Switch keyboard layout (Dvorak / US)" })  -- cycle kb_layout (Dvorak <-> US)
hl.bind(mainMod .. " + CTRL + T",  hl.dsp.exec_cmd("~/.local/bin/cosmic-theme-toggle"), { description = "Dark / light theme" })  -- dark/light, shared with COSMIC
moved("SHIFT + T", "Super+Ctrl+T", hl.dsp.exec_cmd("~/.local/bin/cosmic-theme-toggle"))
hl.bind(mainMod .. " + Q",         hl.dsp.window.close(), { description = "Close window" })
hl.bind(mainMod .. " + F",         hl.dsp.window.fullscreen(), { description = "Fullscreen" })
hl.bind(mainMod .. " + M",         hl.dsp.window.fullscreen({ mode = "maximized" }), { description = "Maximize (bar stays)" })  -- fill the screen, bar stays
hl.bind(mainMod .. " + V",         hl.dsp.exec_cmd("$HOME/.local/bin/clip-menu"), { description = "Clipboard history" })  -- clipboard history
hl.bind(mainMod .. " + SHIFT + V", hl.dsp.window.float({ action = "toggle" }), { description = "Float / tile window" })
hl.bind(mainMod .. " + C",         hl.dsp.exec_cmd("$HOME/.nix-profile/bin/qs ipc call panel toggle"), { description = "Control panel (Quickshell)" })
hl.bind(mainMod .. " + N",         hl.dsp.exec_cmd("$HOME/.nix-profile/bin/qs ipc call bar popup notifs"), { description = "Notifications list (bell pill)" })
-- Alt+Tab: window thumbnails, most recent first; hold Alt and tap Tab, let go to switch (Quickshell Switcher.qml).
-- The old searchable list is still ~/.local/bin/window-switcher.
hl.bind("ALT + Tab",               hl.dsp.exec_cmd("$HOME/.nix-profile/bin/qs ipc call switcher next || $HOME/.local/bin/window-switcher"), { description = "Window switcher" })
hl.bind("ALT + SHIFT + Tab",       hl.dsp.exec_cmd("$HOME/.nix-profile/bin/qs ipc call switcher prev"), { description = "Window switcher (backwards)" })
-- Letting go of Alt picks the window. Done here as well as in Switcher.qml because a quick Alt+Tab
-- lets go before the switcher has the keyboard. Non-consuming, so apps (Emacs) still see Alt released;
-- `commit` does nothing when the switcher is closed.
hl.bind("ALT + Alt_L",             hl.dsp.exec_cmd("$HOME/.nix-profile/bin/qs ipc call switcher commit"), { release = true, transparent = true, non_consuming = true, description = "Window switcher: pick on Alt release" })
hl.bind(mainMod .. " + L",         hl.dsp.exec_cmd("$HOME/.local/bin/lock-now"), { description = "Lock screen" })
-- Log out takes a second press within 4 s (logout-confirm); the first only asks.
hl.bind(mainMod .. " + SHIFT + E", hl.dsp.exec_cmd("$HOME/.local/bin/logout-confirm"), { description = "Log out of Hyprland (press twice)" })
-- Screenshots: saved to ~/Pictures/Screenshots and copied to the clipboard
hl.bind("Print",               hl.dsp.exec_cmd("$HOME/.local/bin/screenshot edit"), { description = "Screenshot: pick a region, then mark it up" })
hl.bind(mainMod .. " + SHIFT + Print", hl.dsp.exec_cmd("$HOME/.local/bin/screenshot region"), { description = "Screenshot: region, no editor" })
hl.bind("SHIFT + Print",       hl.dsp.exec_cmd("$HOME/.local/bin/screenshot window"), { description = "Screenshot: window" })
hl.bind("CTRL + Print",        hl.dsp.exec_cmd("$HOME/.local/bin/screenshot screen"), { description = "Screenshot: whole screen" })
hl.bind(mainMod .. " + Print", hl.dsp.exec_cmd("$HOME/.local/bin/screenshot menu"), { description = "Screenshot menu" })
-- Main-and-stack layouts (the left Dell, portrait Dell and Samsung by default; Super+A to change).
for _, b in ipairs({
    { "SHIFT + Return", "swapwithmaster",   "Main-and-stack, deck, three columns: make this the main window" },
    { "SHIFT + M",      "focusmaster",      "Focus the main window (main-and-stack, deck, three columns)" },
    { "K",              "cyclenext",        "Focus the next window" },
    { "H",              "cycleprev",        "Focus the previous window" },
    { "Y",              "swapnext",         "Swap this window with the next one (down the stack)" },
    { "SHIFT + Y",      "swapprev",         "Swap this window with the previous one (up the stack)" },
    { "SHIFT + I",      "addmaster",        "Main-and-stack: one more main window" },
    { "SHIFT + U",      "removemaster",     "Main-and-stack: one fewer main window" },
    { "X",              "orientationcycle", "Main-and-stack: move the main area (left, top, right, bottom, centre)" },
