-- Desktops that span every monitor (like COSMIC's "workspaces span displays").
-- Desktop N is one workspace per monitor: id N*10 + i, where i counts monitors
-- left to right (so desktop 2 = 21 on the left Dell ... 24 on the laptop when
-- docked; just 21 when undocked). Whenever any monitor lands on a desktop
-- workspace -- keybind, bar click, swipe, scroll -- the workspace.active
-- hook below pulls every other monitor onto the same desktop.
-- Global so `hyprctl eval 'Desk.go(3)'` works from scripts and the bar.
Desk = { syncing = false }

function Desk.monitors()
    local ms = hl.get_monitors()
    table.sort(ms, function(a, b) return a.x < b.x or (a.x == b.x and a.y < b.y) end)
    return ms
end

function Desk.index(mon)
    for i, m in ipairs(Desk.monitors()) do
        if m.name == mon.name then return i end
    end
    return 1
end

function Desk.current()
    local ws = hl.get_active_workspace()
    if ws and ws.id and ws.id >= 11 then return ws.id // 10 end
    return 1
end

function Desk.go(n)
    if Desk.syncing then return end
    n = math.max(1, math.min(10, n))
    Desk.syncing = true
    local ok, err = pcall(function()
        local focused = hl.get_active_monitor()
        local cursor  = hl.get_cursor_pos()
        local moved   = false
        for i, m in ipairs(Desk.monitors()) do
            local want = n * 10 + i
            -- A screen with no workspace of its own (a mirror, or one Hyprland is still
            -- bringing up) must be left alone: focusing it segfaults Hyprland 0.57.2
            -- (crash of 2026-11-11, focusMonitor -> getFocusCandidate on a null workspace).
            local has = m.active_workspace and m.active_workspace.id and m.active_workspace.id >= 1
            if has and m.active_workspace.id ~= want then
                hl.dispatch(hl.dsp.focus({ monitor = m.name }))
                hl.dispatch(hl.dsp.focus({ workspace = want, on_current_monitor = true }))
                moved = true
            end
        end
        -- Focusing a monitor warps the pointer; put focus and pointer back.
        if moved and focused then
            hl.dispatch(hl.dsp.focus({ monitor = focused.name }))
            if cursor then hl.dispatch(hl.dsp.cursor.move({ x = cursor.x, y = cursor.y })) end
        end
    end)
    Desk.syncing = false
    if not ok then hl.notification.create({ text = "Desk.go: " .. tostring(err), duration = 8000 }) end
end

-- Move the focused window to desktop N, same monitor; you follow it there.
function Desk.send(n)
    local mon = hl.get_active_monitor()
    if not mon then return end
    hl.dispatch(hl.dsp.window.move({ workspace = n * 10 + Desk.index(mon) }))
    Desk.go(n)
end

hl.on("workspace.active", function()
    if Desk.syncing then return end
    local ws = hl.get_active_workspace()
    if ws and not ws.special and ws.id and ws.id >= 11 then Desk.go(ws.id // 10) end
end)
-- Undocking leaves the other screens' workspaces (12, 13, 23 ...) on the screen
-- that is left, where no desktop reaches them. Desk.reflow() folds each such
-- window into the last slot that still exists (13 -> 11 on the laptop alone)
-- and remembers the slot it came from in Desk.home, keyed by the window's
-- stable id; when the screens come back it moves the window home again, on
-- whatever desktop it is on by then. A window you moved to another screen
-- yourself in the meantime stays where you put it.
-- The table is kept in a file so a config reload while undocked doesn't forget.
Desk.home      = {}
Desk.last_n    = nil
Desk.home_file = (os.getenv("XDG_RUNTIME_DIR") or "/tmp") .. "/hypr-desk-home"

function Desk.load_home()
    local f = io.open(Desk.home_file, "r")
    if not f then return end
    Desk.last_n = tonumber(f:read("l") or "")
    for line in f:lines() do
        local sid, slot = line:match("^(%S+) (%d+)$")
        if sid then Desk.home[sid] = tonumber(slot) end
    end
    f:close()
end

function Desk.save_home()
    local f = io.open(Desk.home_file, "w")
    if not f then return end
    f:write(tostring(Desk.last_n or ""), "\n")
    for sid, slot in pairs(Desk.home) do f:write(sid, " ", slot, "\n") end
    f:close()
end

function Desk.reflow()
    local ok, err = pcall(function()
        local n = #Desk.monitors()
        if n < 1 then return end
        local last_n, seen = Desk.last_n or n, {}
        for _, w in ipairs(hl.get_windows()) do
            local ws  = w.workspace
            local sid = tostring(w.stable_id)
            seen[sid] = true
            if ws and not ws.special and ws.id and ws.id >= 11 then
                local desk, slot = ws.id // 10, ws.id % 10
                local home = Desk.home[sid]
                -- Not where the last reflow left it: you moved it, so that's home now.
                if home and slot ~= math.min(home, last_n) then home = nil end
                home = home or slot
                local want = math.min(home, n)
                Desk.home[sid] = (home > n) and home or nil
                if want ~= slot and want >= 1 then
                    hl.dispatch(hl.dsp.window.move({ workspace = desk * 10 + want, window = w, follow = false }))
                end
            end
        end
        for sid in pairs(Desk.home) do
            if not seen[sid] then Desk.home[sid] = nil end
        end
        Desk.last_n = n
        Desk.save_home()
    end)
    if not ok then hl.notification.create({ text = "Desk.reflow: " .. tostring(err), duration = 8000 }) end
end

-- Screens come and go one at a time when the dock is (un)plugged; wait for the
-- last of them, line the desktops up, then put the windows where they belong.
function Desk.settle()
    Desk.settle_gen = (Desk.settle_gen or 0) + 1
    local gen = Desk.settle_gen
    hl.timer(function()
        if gen ~= Desk.settle_gen then return end
        Desk.go(Desk.current())
        Desk.reflow()
    end, { timeout = 700, type = "oneshot" })
end

Desk.load_home()

-- Line every screen up on desktop 1 at login, and again when the dock is attached.
hl.on("hyprland.start", function() Desk.go(1) end)
hl.on("monitor.added",   function() Desk.go(Desk.current()); Desk.settle() end)
hl.on("monitor.removed", function() Desk.settle() end)

