-- Laptop panel on/off. Never turns off the last screen.
-- Fn+F5: the EC sends Super+P ("switch display") -> toggle.
-- Lid: closing it while docked turns the panel off; opening turns it back on.
-- (Undocked, logind suspends on lid close, and the guard leaves the panel alone.)
local laptop = { output = "eDP-1", mode = "1920x1080@60.049", position = "6440x840", scale = 1, transform = 0, off = false }
for k, v in pairs((DisplayLayout and DisplayLayout.rules or {})[laptop.output] or {}) do laptop[k] = v end   -- monitors.lua (Settings > Displays) wins
function laptop.set(off, quiet)
    if off == laptop.off then return end
    if off then
        if #hl.get_monitors() < 2 then
            if not quiet then
                hl.exec_cmd("notify-send -a osd 'Laptop screen is the only screen' 'Not turning it off'")
            end
            return
        end
        hl.monitor({ output = laptop.output, disabled = true })
    else
        hl.monitor({ output = laptop.output, mode = laptop.mode, position = laptop.position, scale = laptop.scale, transform = laptop.transform, disabled = false })  -- hl.monitor merges: clear the earlier "off"
    end
    laptop.off = off
end
hl.bind("switch:on:Lid Switch",  function() laptop.set(true, true) end,  { locked = true, description = "Lid closed: laptop screen off when docked" })
hl.bind("switch:off:Lid Switch", function() laptop.set(false, true) end, { locked = true, description = "Lid opened: laptop screen on" })

-- Projector / external display modes, driven by ~/.local/bin/display-menu
-- (Super+P = Fn+F5). The menu works out which output is the projector (anything
-- that isn't the laptop or one of the desk monitors above) and calls, via
-- `hyprctl eval`:  Display.set("extend"|"mirror"|"projector"|"laptop", "<output>")
-- or Display.laptop_toggle().
Display = {}
function Display.set(mode, proj)
    -- hl.monitor merges into the output's earlier rule, so a past "off" or "mirror"
    -- sticks unless it is cleared here (Extend after Mirror used to stay mirrored).
    local on = { output = proj, mode = "preferred", position = "auto", scale = 1, disabled = false, mirror = "" }
    if mode == "extend" or mode == "projector" then
        hl.monitor(on)
    elseif mode == "mirror" then
        on.mirror = laptop.output
        hl.monitor(on)
    elseif mode == "laptop" then
        hl.monitor({ output = proj, disabled = true })
    end
    laptop.set(mode == "projector", true)   -- projector only: panel off; every other mode: panel on
    Desk.go(Desk.current())
end
function Display.laptop_toggle() laptop.set(not laptop.off) end
hl.bind(mainMod .. " + P", hl.dsp.exec_cmd("$HOME/.local/bin/display-menu"), { description = "Displays: extend / mirror / projector" })
