hl.layer_rule({ name = "anim-qs-notif", match = { namespace = "^qs-notifications$" }, animation = "slide right" })
hl.layer_rule({ name = "anim-qs-bar",   match = { namespace = "^qs-bar$" },   no_anim = true })
hl.layer_rule({ name = "blur-qs-popups", match = { namespace = "^qs-bar$" },  blur_popups = true })
-- Things that must simply be there: the frozen frame of the screenshot editor, the lecture
-- overlays (ink, spotlight, key display, countdown) and the island over the clock.
for _, ns in ipairs({ "qs-shot", "qs-lecture-draw", "qs-lecture-spot", "qs-lecture-keys", "qs-lecture-timer", "qs-island", "qs-cam" }) do
    hl.layer_rule({ name = "anim-" .. ns, match = { namespace = "^" .. ns .. "$" }, no_anim = true })
end
-- The full-screen pieces fade in rather than pop.
for _, ns in ipairs({ "qs-dashboard", "qs-overview", "qs-switcher", "qs-sharepick", "qs-saver", "qs-settings" }) do
    hl.layer_rule({ name = "anim-" .. ns, match = { namespace = "^" .. ns .. "$" }, animation = "fade" })
end

-- Zoom: the screen-share toolbar ("You are screen sharing" / "Stop share") is its own
-- window titled as_toolbar. Float it small at the top of the screen, on every desktop,
-- without stealing focus; otherwise it gets tiled into half the monitor.
hl.window_rule({
    name  = "zoom-share-toolbar",
    match = { class = "^Zoom$", title = "^as_toolbar$" },
    -- Zoom draws the green/red buttons at a fixed spot (x ~236-520, centre ~378) inside
    -- a mostly transparent window and doesn't re-layout on resize: 540x30 holds them,
    -- and the move centres the buttons (not the window) just below the bar.
    float            = true,
    pin              = true,
    no_initial_focus = true,
    border_size      = 0,
    no_shadow        = true,
    no_blur          = true,    -- the transparent part would show as a frosted box
    size             = "540 30",
    move             = "(monitor_w*0.5-378) 46",
})
-- Zoom's other bare popups (menus, reactions, the floating video thumbnail) float too.
hl.window_rule({
    name  = "zoom-popups",
    match = { class = "^Zoom$", title = "^(zoom|zoom_linux_float_video_window)$" },
    float            = true,
    no_initial_focus = true,
})

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})

