-- Borders that say something. Tiled windows keep the orange-to-purple gradient
-- (unfocused: grey); these states get their own colour, focused or not:
--   floating  solid Regalia purple        pinned (on every desktop)  amber
hl.window_rule({ name = "border-floating", match = { float = true }, border_color = "rgba(522d80ee)" })
hl.window_rule({ name = "border-pinned",   match = { pin = true },   border_color = "rgba(f5a623ee)" })

-- ---- Window feel: dialogs, small tools and picture-in-picture (2026-11-11) ----
-- Tiled windows can be resized by dragging the gap between them, and floating windows
-- snap to screen edges and to each other when dragged close.
hl.config({ general = { resize_on_border = true, snap = { enabled = true } } })
-- Mouse resizing of tiled windows that follows the pointer (strict-resize plugin, source +
-- build.sh in ~/.local/share/hypr-strict-resize). On the edge between two windows only that
-- edge's direction moves; where three or more windows meet (within junction_radius px of
-- the pointer) both do, and a four-way cross stays a cross. The hover cursor shows which it
-- will be, and a gap with nothing to resize (screen edges, deck) shows none. Super+right-drag
-- inside a window goes by thirds: edge strip, corner cell, or nearest corner from the centre.
-- It also makes the custom layouts' dividers draggable (layouts.lua). The plugin is built
-- for one Hyprland version: after an update it refuses to load (a notification says so)
-- and resizing goes back to stock until build.sh is run again.
do
    local so = os.getenv("HOME") .. "/.local/lib/hyprland/strict-resize.so"
    local f = io.open(so, "r")
    if f then
        f:close()
        local ok, err = pcall(hl.plugin.load, so)
        if not ok then hl.notification.create({ text = "strict-resize: " .. tostring(err), duration = 10000 }) end
        -- the setting only exists once the plugin is in; guarded so a plugin that refused to load is not a config error
        pcall(hl.config, { plugin = { strictresize = { junction_radius = 48 } } })
        pcall(function() Layouts.sync_axes() end)       -- which directions each desktop's layout can resize
    end
end
-- File pickers and password prompts: centred, floating, with the rest of the desktop dimmed
-- so they read as "answer this first".
-- ncmpcpp (~/.local/bin/music starts ghostty with this class) lives on its own special
-- workspace, floating and centred; Super+` (or a click on the bar's media cover) summons it.
hl.window_rule({ name = "ncmpcpp",
    match = { class = "^org\\.tsr\\.ncmpcpp$" },
    workspace = "special:music silent",
    float = true, center = true, size = "(monitor_w*0.62) (monitor_h*0.62)" })
hl.workspace_rule({ workspace = "special:music", gaps_out = 48, gaps_in = 6 })
-- The Emacs music library (the mpc.el frame named "Music"; ~/.emacs.d/docs/music.org) does
-- the same on special:library: Super+Shift+` (~/.local/bin/music-library) or C-c m l in Emacs.
hl.window_rule({ name = "emacs-music",
    match = { class = "^emacs$", title = "^Music$" },
    workspace = "special:library",
    float = true, center = true, size = "(monitor_w*0.62) (monitor_h*0.62)" })
hl.workspace_rule({ workspace = "special:library", gaps_out = 48, gaps_in = 6 })
-- Keymapp runs in the background (keymapp.service) so its Moonlander heatmap keeps counting;
-- its window waits on a hidden special workspace.  The launcher entry (keymapp-toggle) shows it.
hl.window_rule({ name = "keymapp",
    match = { class = "^keymapp$" },
    workspace = "special:keymapp silent",
    float = true, center = true, size = "(monitor_w*0.62) (monitor_h*0.72)" })
-- Guard for the parking-lot special workspaces above (2026-11-18). With one of them shown, a
-- window opened by anything else lands on it (focus sits there), and because a shown special
-- overlays every desktop that window then "follows" each workspace switch. Seen when Keymapp
-- quit at undock with special:keymapp still up: Firefox and Emacs opened onto it. Such a
-- window goes to the desktop underneath instead, and the special is put away so you see it.
-- Owners are matched on class (and title for the Emacs library frame); their own dialogs share
-- the class, so they stay. special:magic (Super+S scratchpad) is yours to fill: not guarded.
SpecialOwners = {
    keymapp = function(w) return w.class == "keymapp" end,
    music   = function(w) return w.class == "org.tsr.ncmpcpp" end,
    library = function(w) return w.class == "emacs" and w.title == "Music" end,
    lights  = function(w) return w.class == "edu.clemson.tsranso.GvmLight" end,
}
function SpecialOwners.stray(w)
    local ws = w and w.workspace
    if not (ws and ws.special and ws.name) then return nil end
    local key = ws.name:gsub("^special:", "")
    local owns = SpecialOwners[key]
    if type(owns) ~= "function" or owns(w) then return nil end
    return key
end
hl.on("window.open", function(w)
    local ok, err = pcall(function()
        local key = SpecialOwners.stray(w)
        if not key then return end
        local mon = w.monitor or hl.get_active_monitor()
        local under = mon and mon.active_workspace
        if not (under and under.id) then return end
        hl.dispatch(hl.dsp.window.move({ workspace = under.id, window = w, follow = false }))
        local shown = hl.get_active_special_workspace(mon)
        if shown and shown.name == "special:" .. key then
            hl.dispatch(hl.dsp.workspace.toggle_special(key))
        end
        hl.dispatch(hl.dsp.focus({ window = "address:" .. w.address }))
    end)
    if not ok then hl.notification.create({ text = "SpecialOwners: " .. tostring(err), duration = 8000 }) end
end)
-- And switching desktops puts any shown special away, so nothing on one can ride along.
hl.config({ binds = { hide_special_on_workspace_change = true } })
hl.window_rule({ name = "dialog-file",
    match = { title = "^(Open|Save|Select|Choose|Export|Import|Upload)( [A-Za-z]+)? (File|Files|Folder|Folders|Directory|As|Image|Document).*$" },
    float = true, center = true, size = "960 640", dim_around = true })
hl.window_rule({ name = "dialog-portal",
    match = { class = "^(xdg-desktop-portal-gtk|xdg-desktop-portal-gnome)$" },
    float = true, center = true, dim_around = true })
hl.window_rule({ name = "dialog-auth",
