    float = true, center = true, dim_around = true })
-- Small utility windows float in the middle instead of taking half the screen.
hl.window_rule({ name = "tool-windows",
    match = { class = "^(org.pulseaudio.pavucontrol|pavucontrol|com.saivert.pwvucontrol|org.gnome.Calculator|nm-connection-editor|blueman-manager)$" },
    float = true, center = true, size = "880 620" })
-- Picture-in-picture video: a small pinned window in the bottom-right corner of the screen,
